 <?php $__env->startSection('title','Vacantes'); ?> <?php $__env->startSection('content'); ?><section class="page-head"><span class="eyebrow">OPORTUNIDADES PARA CRECER</span><h1>Encuentra tu próxima<br><em>oportunidad.</em></h1><p>Explora vacantes y da el siguiente paso en tu vida profesional.</p></section><form class="filters" method="GET"><input name="q" value="<?php echo e(request('q')); ?>" placeholder="Cargo, empresa o palabra clave"><input name="location" value="<?php echo e(request('location')); ?>" placeholder="Ciudad o ubicación"><select name="modality"><option value="">Todas las modalidades</option><?php $__currentLoopData = ['Presencial','Remoto','Híbrido']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $m): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option <?php if(request('modality')===$m): echo 'selected'; endif; ?>><?php echo e($m); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><button class="btn primary">Buscar</button></form><div class="results-top"><strong><?php echo e($jobs->total()); ?> oportunidades encontradas</strong><span>Ordenadas por más recientes</span></div><div class="job-grid"><?php $__empty_1 = true; $__currentLoopData = $jobs; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $job): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><article class="job-card"><div class="job-top"><div class="company-avatar"><?php echo e(strtoupper(substr($job->company_name,0,1))); ?></div><span class="pill"><?php echo e($job->modality); ?></span></div><h3><a href="<?php echo e(route('jobs.show',$job)); ?>"><?php echo e($job->title); ?></a></h3><p class="company-name"><?php echo e($job->company_name); ?></p><div class="job-meta"><span>⌖ <?php echo e($job->location); ?></span><span>◷ <?php echo e($job->type); ?></span></div><div class="job-card-bottom"><span><?php echo e($job->salary ?: 'Salario a convenir'); ?></span